function Act($e){$v=$null;if($e.TryGetCurrentPattern([Windows.Automation.InvokePattern]::Pattern,[ref]$v)){$v.Invoke();return};if($e.TryGetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern,[ref]$v)){$v.Select();return};throw ('No activation pattern for '+$e.Current.Name)}
function One($root,$condition){$items=@($root.FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.Condition]::TrueCondition)|Where-Object $condition);if($items.Count -ne 1){throw ('Expected one control; found '+$items.Count)};return $items[0]}
