 $root=[Windows.Automation.AutomationElement]::FromHandle($handle);$export=One $root {$_.Current.Name -eq '导出' -and $_.Current.ControlType.ProgrammaticName -in @('ControlType.ListItem','ControlType.MenuItem') -and -not $_.Current.IsOffscreen};Act $export;Start-Sleep -Milliseconds 100
 $root=[Windows.Automation.AutomationElement]::FromHandle($handle);$tab=One $root {$_.Current.Name -eq '创建动态 GIF' -and $_.Current.ControlType.ProgrammaticName -eq 'ControlType.TabItem' -and -not $_.Current.IsOffscreen};Act $tab;Start-Sleep -Milliseconds 100
 $root=[Windows.Automation.AutomationElement]::FromHandle($handle);$g=$root.FindFirst([Windows.Automation.TreeScope]::Descendants,(New-Object Windows.Automation.PropertyCondition([Windows.Automation.AutomationElement]::AutomationIdProperty,'GroupExportToAnimatedGif')));if(-not $g){throw 'Real Animated GIF group absent'};return $g
}
function EditPattern($g,$name){$e=One $g {$_.Current.Name -eq $name -and $_.Current.ControlType.ProgrammaticName -eq 'ControlType.Edit'};return $e.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern)}
function SetGifQuality([IntPtr]$handle,[string]$label){
