 $vp=$q.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern)
 if($vp.Current.Value -eq $label){return}
 $ep=$q.GetCurrentPattern([Windows.Automation.ExpandCollapsePattern]::Pattern);$ep.Expand();Start-Sleep -Milliseconds 100
 $root=[Windows.Automation.AutomationElement]::FromHandle($handle)
 $choices=@($root.FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.Condition]::TrueCondition)|Where-Object {$_.Current.Name -eq $label -and $_.Current.ControlType.ProgrammaticName -eq 'ControlType.ListItem' -and -not $_.Current.IsOffscreen})
 if($choices.Count -eq 0){$ep.Collapse();throw 'Own quality option absent'}
