 if($vp.Current.Value -ne $label){throw 'Native quality selection readback mismatch'}
}
$app=New-Object -ComObject PowerPoint.Application;$p=$null;$h=[IntPtr]::Zero;$states=$null;$done=$false;$restore=@{};$stage='open-own-deck'
try{
 $app.Visible=-1;$p=$app.Presentations.Open([IO.Path]::GetFullPath($Deck),-1,0,-1);$p.Windows.Item(1).Activate();$p.Slides.Item(1).Select();if($p.Slides.Count -ne 1 -or $app.ActivePresentation.FullName -ne [IO.Path]::GetFullPath($Deck)){throw 'Own single-slide presentation guard failed'};$h=[NativeGifExportUI]::Own([IO.Path]::GetFileNameWithoutExtension($Deck));if($h -eq [IntPtr]::Zero){throw 'Own window absent'};$g=GifPanel $h
