 [NativeGifExportUI]::SetOwnFilename($dialog,$hostH,$editH,[IO.Path]::GetFullPath($Gif));@{dialogHwnd=$dialog.ToInt64();dialogPid=[NativeGifExportUI]::Pid($dialog);ownerHwnd=$h.ToInt64();filenameHost=$hostH.ToInt64();filenameEdit=$editH.ToInt64();filenameClass=[NativeGifExportUI]::Class($editH);filenameParentValidated=$true;saveButtonClass=[NativeGifExportUI]::Class([NativeGifExportUI]::GetDlgItem($dialog,1));outputPath=[IO.Path]::GetFullPath($Gif)}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $Evidence 'save-dialog-guard.json') -Encoding utf8
 $stage='save-native-gif';[NativeGifExportUI]::ClickOwnDialogButton($dialog,1)
