}catch{@{stage=$stage;message=$_.Exception.Message;scriptStackTrace=$_.ScriptStackTrace;position=$_.InvocationInfo.PositionMessage}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $Evidence 'error.json') -Encoding utf8;throw}
