 if($states -and $p -and $restore.ownerEnabled){try{$g=GifPanel $h;$s=EditPattern $g '花在每张幻灯片上的秒数';$f=EditPattern $g '导出范围内的第一张幻灯片';$l=EditPattern $g '导出范围内的最后一张幻灯片';$t=(One $g {$_.Current.Name -eq '将背景设置为透明' -and $_.Current.ControlType.ProgrammaticName -eq 'ControlType.CheckBox'}).GetCurrentPattern([Windows.Automation.TogglePattern]::Pattern);$s.SetValue($states.seconds);$f.SetValue($states.first);$l.SetValue($states.last);if([int]$t.Current.ToggleState -ne $states.transparent){$t.Toggle()};$restore.secondsRestored=$s.Current.Value -eq $states.seconds;$restore.firstRestored=$f.Current.Value -eq $states.first;$restore.lastRestored=$l.Current.Value -eq $states.last;$restore.transparentRestored=[int]$t.Current.ToggleState -eq $states.transparent;$qRestore=One $g {$_.Current.Name -eq 'GIF 质量' -and $_.Current.ControlType.ProgrammaticName -eq 'ControlType.ComboBox'};$qValue=$qRestore.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern);SetGifQuality $h $states.qualityBefore;$restore.qualityRestored=$qValue.Current.Value -eq $states.qualityBefore}catch{$restore.settingsError=$_.Exception.Message}}
